--[[ generated by midnight from midnight/resurrect/util.mn, edit that instead ]] local _MODULE = {} function _MODULE.user_command(command_name, cmds)


  local function complete(arg_lead, cmd_line)
    local words = vim.split(cmd_line, "%s+", {trimempty = true})

    if #words > 2 or #words == 2 and arg_lead == "" then
      return {}
    end
    local pattern = arg_lead:lower():gsub(".", function(c)
      local p = vim.pesc(c)
      return tostring(p) .. "[^" .. tostring(p) .. "]*"
    end)
    return 

    vim.iter(vim.tbl_keys(cmds)):filter(function(name) return name ~= "default" and name:lower():find(pattern) ~= nil end):totable()
  end

  vim.api.nvim_create_user_command(command_name, function(opts)
    local args = vim.split(opts.args, "%s+", {trimempty = true})
    if #args == 0 then
      cmds.default(opts)
      return
    end

    local name = table.remove(args, 1)
    local cmd = cmds[name]
    if cmd == nil then
      vim.notify(tostring(command_name) .. ": unknown command '" .. tostring(name) .. "'", vim.log.levels.ERROR)
      return
    end

    if type(cmd) == "function" then
      cmd(opts)
    elseif cmd.basic then
      cmd.cb(args) else

      cmd.cb(opts)
    end
  end, {
  nargs = "*", 
  bang = true, 
  complete = complete
  })
end

function _MODULE.file_exists(name)
  local stat = vim.uv.fs_stat(name)
  return stat ~= nil and stat.type == "file"
end

--- opens files (w/ their saved cursor), and returns the ones that no longer exist
function _MODULE.open_files(files)
  local dead_files = {}
  for _, f in ipairs(files) do
    if _MODULE.file_exists(f.path) then

      vim.cmd.edit(vim.fn.fnameescape(f.path))
      if f.row and f.col then

        local row = math.min(f.row, vim.api.nvim_buf_line_count(0))
        vim.api.nvim_win_set_cursor(0, {row, f.col})
      end else

      table.insert(dead_files, f)
    end
  end
  return dead_files
end

--- listed buffers w/ unsaved changes (which close_files discards)
function _MODULE.modified_buffers()
  return 

  vim.iter(vim.api.nvim_list_bufs()):filter(function(b) return vim.bo[b].buflisted and vim.bo[b].modified end):totable()
end

--- deletes every listed buffer, discarding unsaved changes (see modified_buffers)
function _MODULE.close_files()
  vim.cmd("%bd!")
end

function _MODULE.session_shortname(name)
  return name:match("^([^:]*)")
end
return _MODULE
